#!/usr/bin/env bash
# Install the repository hooks. Run once per clone.
#
# Installs a `commit-msg` hook that rejects commits without a
# `Signed-off-by` trailer (DCO). Merge commits are exempt.
set -euo pipefail

cd "$(dirname "$0")/.."

hooks_dir="$(git rev-parse --git-path hooks)"
mkdir -p "$hooks_dir"

cat > "$hooks_dir/commit-msg" <<'HOOK'
#!/usr/bin/env bash
# Reject commits without a DCO sign-off.
set -euo pipefail

msg_file="$1"

# Merge commits are generated by git and have no body to sign.
if head -n 1 "$msg_file" | grep -q '^Merge '; then
  exit 0
fi

if ! grep -qiE '^Signed-off-by: .+ <.+@.+>$' "$msg_file"; then
  echo "error: commit message is missing a Signed-off-by trailer." >&2
  echo "" >&2
  echo "       Commit with:  git commit -s" >&2
  echo "       See CONTRIBUTING.md (Developer Certificate of Origin)." >&2
  exit 1
fi
HOOK

chmod +x "$hooks_dir/commit-msg"
echo "installed $hooks_dir/commit-msg"
